import js from '@eslint/js';
import tseslint from 'typescript-eslint';

export default tseslint.config(
  {
    ignores: [
      'dist/**',
      'dist-test/**',
      'media/webview.js',
      // Generated by dev/harness/generate.mjs.
      'dev/harness/fixture.js',
      'node_modules/**',
      'coverage/**',
      '.vscode-test/**',
    ],
  },
  js.configs.recommended,
  ...tseslint.configs.recommended,
  {
    rules: {
      '@typescript-eslint/no-explicit-any': 'error',
      '@typescript-eslint/consistent-type-imports': ['error', { prefer: 'type-imports' }],
      eqeqeq: ['error', 'always', { null: 'ignore' }],
      'no-console': 'error',
    },
  },
  {
    // PRD §10 / Plan 01: the pure modules must stay runnable under plain Node so the anchoring
    // core can be tested without a VS Code host. This rule is the mechanical enforcement of that
    // constraint — it matters most from Phase 2 on, when `vscode` is a legitimate import one
    // directory over.
    // `panel/messages.ts` joins the list from Phase 2 on: it is bundled into the *webview*, where
    // `vscode` does not exist, so an import there fails at bundle time with a confusing error.
    files: [
      'src/anchor/**/*.ts',
      'src/render/**/*.ts',
      'src/prompt/**/*.ts',
      'src/panel/messages.ts',
      // `panel/notices.ts` holds specified user-facing wording. It is kept `vscode`-free purely so
      // the strings can be asserted by a unit test instead of by a manual acceptance pass.
      'src/panel/notices.ts',
      // Phase 3: the sidecar naming rules and the validation guard are the parts of the store with
      // landmines in them (Windows separators, hand-edited JSON), so they are kept `vscode`-free
      // and unit-tested. `store/ReviewStore.ts` is deliberately *not* on this list — it is the
      // vscode-facing half.
      'src/store/sidecarPath.ts',
      'src/store/reviewFile.ts',
      // Phase 4: the debounce behind change detection. `changeWatcher.ts` is deliberately *not* on
      // this list — it is the `vscode` half — but the timing rules are pulled out here so they can
      // be asserted with fake timers instead of a stopwatch in the integration suite.
      'src/detect/coalesce.ts',
      // The rewrite trigger rule, kept pure so it is a unit test rather than something only
      // reproducible by wrecking a file in a dev host.
      'src/detect/rewrite.ts',
      // D17. `scopeOf` decides what region a comment is about and `changedRanges` decides what moved
      // since the baseline; between them they hold every edge case the section signal can hit
      // (partial headings, nested levels, deletions at a block seam). All of it is reachable from a
      // string and a `PlainTextDoc`, so none of it should need a dev host to test.
      'src/detect/scope.ts',
      'src/detect/changedRanges.ts',
    ],
    rules: {
      'no-restricted-imports': [
        'error',
        {
          paths: [
            {
              name: 'vscode',
              message:
                'Pure modules (anchor/, render/, prompt/, the store naming+validation halves) and the webview-bundled message contract must not import vscode — see PRD §10 Phase 1.',
            },
          ],
        },
      ],
    },
  },
  {
    // Build scripts are plain ESM JavaScript, so `no-undef` is active (typescript-eslint only
    // disables it for .ts) and the globals it needs must be declared. Inline rather than adding
    // the `globals` package for four names.
    files: ['esbuild.mjs', 'scripts/**/*.mjs', 'dev/**/*.mjs'],
    languageOptions: {
      globals: { process: 'readonly', console: 'readonly', URL: 'readonly', Buffer: 'readonly' },
    },
    rules: {
      // Build tooling reports to the terminal; that is its interface.
      'no-console': 'off',
    },
  },
  {
    files: ['src/test/**/*.ts'],
    rules: {
      // Perf tests report their measurements; that is the whole point of running them.
      'no-console': 'off',
    },
  },
);
